<script setup>
import {ref,onMounted} from 'vue';
const text=ref(''),status=ref(''),key='study-space-optimization-notebook-v1';
onMounted(()=>{try{text.value=localStorage.getItem(key)||''}catch{status.value='当前浏览器不能保存；请复制笔记或导出。'}});
function save(){try{localStorage.setItem(key,text.value);status.value='笔记已保存在当前浏览器。'}catch{status.value='保存失败，请导出备份。'}}
function record(k){try{const v=JSON.parse(localStorage.getItem(k)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}}
function download(){try{const content=JSON.stringify({version:1,note:text.value,progress:Object.fromEntries(Object.entries(record('ml-course-progress-v1')).filter(([id])=>id.startsWith('opt-')||id.includes('optimization'))),mastery:Object.fromEntries(Object.entries(record('ml-course-mastery-v1')).filter(([id])=>id.startsWith('opt-')||id.includes('optimization')))},null,2);const u=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='study-space-optimization-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status.value='已导出最优化笔记及阅读记录。'}catch{status.value='导出失败；请直接复制笔记。'}}
async function restore(e){try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||typeof data.note!=='string')throw Error();text.value=data.note;save();for(const [field,k] of [['progress','ml-course-progress-v1'],['mastery','ml-course-mastery-v1']])if(data[field]&&typeof data[field]==='object'&&!Array.isArray(data[field])){const old=JSON.parse(localStorage.getItem(k)||'{}');for(const [id,value] of Object.entries(data[field]))if((id.startsWith('opt-')||id.includes('optimization'))&&typeof value==='boolean')old[id]=value;localStorage.setItem(k,JSON.stringify(old));}status.value='最优化记录已合并；刷新页面查看进度。'}catch{status.value='无法导入：请选择本站导出的有效笔记 JSON。'}e.target.value='';}
</script>
<template><section class="opt-notebook" aria-label="学习笔记"><h3>把判断写下来 / Learning evidence</h3><p>记录“我预测什么、实际怎样、用了哪个条件、仍不懂哪里”。笔记和勾选记录只保存在此浏览器，不会自动同步到其他设备。</p><label for="opt-note">我的问题、实验预测与英文摘要</label><textarea id="opt-note" v-model="text" @input="save" rows="6" placeholder="模型的变量是……；我认为增大步长会……；这个结论要求……"/><div><button type="button" @click="download">导出备份</button><label class="import">导入备份 <input type="file" accept=".json,application/json" @change="restore"></label></div><p aria-live="polite">{{status}}</p></section></template>
<style scoped>.opt-notebook{padding:20px;border:1px solid var(--vp-c-divider);border-radius:12px;margin:24px 0;background:var(--vp-c-bg-soft)}textarea{display:block;width:100%;padding:12px;border:1px solid var(--vp-c-divider);background:var(--vp-c-bg);border-radius:8px;margin:8px 0;color:var(--vp-c-text-1);resize:vertical}button,.import{display:inline-block;padding:8px 14px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:8px 8px 0 0;font-size:14px}.import input{display:block;max-width:100%;font-size:12px}p{font-size:14px}</style>
